package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme implementation.
// If parsing fails, returns the default theme along with the error.
//
// The JSON structure supports:
//   - "Colors": map of color name to hex string (applied to all variants)
//   - "Colors-dark": map of color name to hex string (applied only in dark variant)
//   - "Colors-light": map of color name to hex string (applied only in light variant)
//   - "Sizes": map of size name to float32 value
//   - "Fonts": map of font style ("regular", "bold", "boldItalic", "monospace") to URI string
//   - "Icons": map of icon name to URI string
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme implementation.
// If parsing fails, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&raw); err != nil {
		return DefaultTheme(), err
	}

	jt := &jsonTheme{
		colors:      make(map[string]map[fyne.ThemeVariant]color.Color),
		sizes:       make(map[string]float32),
		fonts:       make(map[fyne.TextStyle]fyne.Resource),
		icons:       make(map[string]fyne.Resource),
		defaultTheme: DefaultTheme(),
	}

	// Parse colors (generic)
	if colors, ok := raw["Colors"].(map[string]interface{}); ok {
