				}
			}
		}
	}

	// Parse colors (dark variant)
	if colorsDark, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, hexValue := range colorsDark {
			if hexStr, ok := hexValue.(string); ok {
				c, err := parseHexColor(hexStr)
				if err == nil {
