// parseHexColor parses a hex color string in various formats:
// - 3 digits: "abc" or "#abc" -> 0xaa 0xbb 0xcc 0xff
// - 4 digits: "abcd" -> 0xaa 0xbb 0xcc 0xdd (note: "#abcd" is treated as # + 3-digit)
// - 6 digits: "a1b2c3" or "#a1b2c3" -> 0xa1 0xb2 0xc3 0xff
// - 8 digits: "a1b2c3f4" or "#a1b2c3f4" -> 0xa1 0xb2 0xc3 0xf4
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	var err error

	switch len(hex) {
	case 3:
		// RGB: each char is doubled
		r, err = parseHexByte(string(hex[0]) + string(hex[0]))
		if err != nil {
			return color.RGBA{}, err
		}
		g, err = parseHexByte(string(hex[1]) + string(hex[1]))
		if err != nil {
			return color.RGBA{}, err
		}
		b, err = parseHexByte(string(hex[2]) + string(hex[2]))
		if err != nil {
			return color.RGBA{}, err
		}
		a = 0xff
	case 4:
		// RGBA: each char is doubled
		r, err = parseHexByte(string(hex[0]) + string(hex[0]))
		if err != nil {
			return color.RGBA{}, err
		}
		g, err = parseHexByte(string(hex[1]) + string(hex[1]))
		if err != nil {
			return color.RGBA{}, err
		}
		b, err = parseHexByte(string(hex[2]) + string(hex[2]))
		if err != nil {
			return color.RGBA{}, err
		}
		a, err = parseHexByte(string(hex[3]) + string(hex[3]))
		if err != nil {
			return color.RGBA{}, err
		}
	case 6:
		// RRGGBB
		r, err = parseHexByte(hex[0:2])
		if err != nil {
			return color.RGBA{}, err
		}
		g, err = parseHexByte(hex[2:4])
		if err != nil {
			return color.RGBA{}, err
		}
		b, err = parseHexByte(hex[4:6])
		if err != nil {
			return color.RGBA{}, err
		}
		a = 0xff
	case 8:
		// RRGGBBAA
		r, err = parseHexByte(hex[0:2])
		if err != nil {
			return color.RGBA{}, err
		}
		g, err = parseHexByte(hex[2:4])
		if err != nil {
			return color.RGBA{}, err
		}
		b, err = parseHexByte(hex[4:6])
		if err != nil {
			return color.RGBA{}, err
		}
		a, err = parseHexByte(hex[6:8])
		if err != nil {
			return color.RGBA{}, err
		}
	default:
		return color.RGBA{}, fmt.Errorf("invalid hex color format: %s", hex)
	}

	return color.RGBA{R: r, G: g, B: b, A: a}, nil
}

func parseHexByte(s string) (uint8, error) {
	val, err := strconv.ParseUint(s, 16, 8)
	if err != nil {
		return 0, err
	}
	return uint8(val), nil
}

