	if sizes, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, value := range sizes {
			if floatVal, ok := value.(float64); ok {
				jt.sizes[name] = float32(floatVal)
			}
		}
	}

	// Parse fonts
	if fonts, ok := raw["Fonts"].(map[string]interface{}); ok {
		for style, uriValue := range fonts {
			if uriStr, ok := uriValue.(string); ok {
				uri, err := storage.ParseURI(uriStr)
				if err == nil {
					res, err := storage.LoadResourceFromURI(uri)
					if err == nil {
						switch style {
