package binding

import (
	"fmt"
	"sync"
)

// NewSprintf returns a String binding that formats its content using the provided format string.
// The binding is updated automatically whenever any of the source DataItems change.
// It provides a Set() method that parses the input using fmt.Sscanf to update the source bindings.
//
// Since: 2.2
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		return NewString() // empty binding if no sources
	}

	ret := &stringFromBinding{
		base:    base{},
		format:  format,
		sources: b,
	}

	// Create listener for each source
	listener := NewDataListener(ret.update)
	for _, source := range b {
		source.AddListener(listener)
	}

	return ret
}

// StringToStringWithFormat creates a bidirectional binding that formats a source String using fmt.Sprintf
// when reading and parses using fmt.Sscanf when writing.
//
// Since: 2.2
func StringToStringWithFormat(source String, format string) String {
	if source == nil {
		return NewString()
	}

	ret := &stringFormatBinding{
		base:   base{},
		format: format,
		source: source,
	}

	// Listen to source changes
	listener := NewDataListener(ret.sourceChanged)
	source.AddListener(listener)

	return ret
}

type stringFromBinding struct {
	base
	format  string
	sources []DataItem
	lock    sync.RWMutex
	cache   string
}

func (s *stringFromBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		val, err := getValue(source)
		if err != nil {
			return "", err
		}
		values[i] = val
	}

	s.cache = fmt.Sprintf(s.format, values...)
	return s.cache, nil
}

func (s *stringFromBinding) Set(str string) error {
	// Parse the string back to source values
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		values[i] = getPointer(source)
	}

	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}
	if n != len(s.sources) {
		return fmt.Errorf("expected %d values, scanned %d", len(s.sources), n)
	}

	// Update each source
	for i, source := range s.sources {
		if err := setValue(source, values[i]); err != nil {
			return err
		}
	}

	return nil
}

func (s *stringFromBinding) update() {
	s.trigger()
}

func (s *stringFromBinding) trigger() {
	s.lock.Lock()
	listeners := s.listeners
	s.lock.Unlock()

	for _, listener := range listeners {
		listener.DataChanged()
	}
}

type stringFormatBinding struct {
	base
	format string
	source String
	lock   sync.RWMutex
}

func (s *stringFormatBinding) Get() (string, error) {
	val, err := s.source.Get()
	if err != nil {
		return "", err
	}
	return fmt.Sprintf(s.format, val), nil
}

func (s *stringFormatBinding) Set(str string) error {
	var val string
	n, err := fmt.Sscanf(str, s.format, &val)
	if err != nil {
		return err
	}
	if n != 1 {
		return fmt.Errorf("expected 1 value, scanned %d", n)
	}
	return s.source.Set(val)
}

func (s *stringFormatBinding) sourceChanged() {
	s.lock.Lock()
	listeners := s.listeners
	s.lock.Unlock()

	for _, listener := range listeners {
		listener.DataChanged()
	}
}

// Helper functions to extract values from different DataItem types
func getValue(item DataItem) (interface{}, error) {
	switch v := item.(type) {
	case Bool:
		return v.Get()
	case Float:
		return v.Get()
	case Int:
		return v.Get()
	case String:
		return v.Get()
	case Rune:
		return v.Get()
	default:
		return nil, fmt.Errorf("unsupported binding type: %T", item)
	}
}

// Helper to get a pointer for Sscanf
func getPointer(item DataItem) interface{} {
	switch item.(type) {
	case Bool:
		var b bool
		return &b
	case Float:
		var f float64
		return &f
	case Int:
		var i int
		return &i
	case String:
		var s string
		return &s
	case Rune:
		var r rune
		return &r
	default:
		return nil
	}
}

// Helper to set values back to different DataItem types
func setValue(item DataItem, ptr interface{}) error {
	switch v := item.(type) {
	case Bool:
		if b, ok := ptr.(*bool); ok {
			return v.Set(*b)
		}
	case Float:
		if f, ok := ptr.(*float64); ok {
			return v.Set(*f)
		}
	case Int:
		if i, ok := ptr.(*int); ok {
			return v.Set(*i)
		}
	case String:
		if s, ok := ptr.(*string); ok {
			return v.Set(*s)
		}
	case Rune:
		if r, ok := ptr.(*rune); ok {
			return v.Set(*r)
		}
	}
	return fmt.Errorf("type mismatch for binding")
}

