func (c *Container) Remove(obj CanvasObject) {
	for i, o := range c.Objects {
		if o != obj {
			continue
		}
		removed := make([]CanvasObject, len(c.Objects)-1)
		copy(removed, c.Objects[:i])
		copy(removed[i:], c.Objects[i+1:])

		c.Objects = removed
		c.layout()
		return
	}
}

