type allStrings struct {
	list []string
}

// Validate checks if the input string is present in the allowed list of strings.
func (v *allStrings) Validate(input interface{}) error {
	text, ok := input.(string)
	if !ok {
		return errors.New("value must be a string")
	}

	for _, allowed := range v.list {
		if text == allowed {
			return nil
		}
	}

	return errors.New("value not in allowed list")
}

